def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network referral rule: self_employed + requested_limit > 6000
    # -> queue_review instead of issuing. A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000
            and decision == "approve"):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    # refer (or any other undecided state)
    return {"action": "queue_review", "limit": 0}
